package com.naimat.autotimelinesync.tests;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import android.view.accessibility.*;import com.naimat.autotimelinesync.*;import org.json.*;import java.util.*;

final class SyncTests {
 static void tap(TestRunner t,AccessibilityNodeInfo node)throws Exception{Rect bounds=new Rect();node.getBoundsInScreen(bounds);t.ok(!bounds.isEmpty(),"Control has no visible bounds");try(android.os.ParcelFileDescriptor fd=t.getUiAutomation().executeShellCommand("input tap "+bounds.centerX()+" "+bounds.centerY());java.io.FileInputStream in=new java.io.FileInputStream(fd.getFileDescriptor())){byte[] b=new byte[256];while(in.read(b)!=-1){}}}
 static AccessibilityNodeInfo node(AccessibilityNodeInfo root,String text){if(root==null)return null;if(text.equalsIgnoreCase(root.getText()==null?"":root.getText().toString()))return root;for(int i=0;i<root.getChildCount();i++){AccessibilityNodeInfo n=node(root.getChild(i),text);if(n!=null)return n;}return null;}
 static Button button(android.view.View view,String text){if(view instanceof Button&&text.contentEquals(((Button)view).getText()))return (Button)view;if(view instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)view;for(int i=0;i<g.getChildCount();i++){Button b=button(g.getChildAt(i),text);if(b!=null)return b;}}return null;}
 static void run(TestRunner t)throws Exception{
  t.getUiAutomation().adoptShellPermissionIdentity("android.permission.READ_CLIPBOARD_IN_BACKGROUND");Context c=t.c;MainActivity a=t.activity;String original=t.original;AccessibilityNodeInfo done=node(t.getUiAutomation().getRootInActiveWindow(),"Done");if(done!=null){done.performAction(AccessibilityNodeInfo.ACTION_CLICK);Thread.sleep(300);}
  t.test("B contract and exact attached V5.2.5 prompt",()->{t.ok(SyncSupport.CONTRACT.equals("ATS_SYNC_2026-10-B"),"Contract drift");String prompt=a.masterPromptText();t.ok(prompt.startsWith("======================================================================")&&prompt.contains("UNIVERSAL_PIPELINE_FINAL_V5.2.5")&&prompt.length()>100000,"Prompt missing/truncated");});
  t.test("three independent errors in one pass and canonical copy",()->{JSONObject j=new JSONObject(original);j.put("style",new JSONObject().put("seed",2147483648L));j.getJSONObject("caption_style").put("preset","Hormozi Style").put("animation","POP");j.getJSONArray("captions").getJSONObject(0).put("id","1");SyncSupport.Report r=SyncSupport.validate(c,j.toString());String message=r.copy();t.ok(!r.valid()&&message.startsWith(SyncSupport.HEADER+"\n"+SyncSupport.COLUMNS),"Wrong exchange format");t.ok(message.contains("$.style.seed |")&&message.contains("$.caption_style.animation |")&&message.contains("$.captions[0].id |"),"Missing independent path "+message);});
  t.test("bad SFX offsets -301 and 301 collected",()->{for(int offset:new int[]{-301,301}){JSONObject j=new JSONObject(original);j.getJSONArray("scenes").getJSONObject(1).put("sfx",new JSONArray().put(new JSONObject().put("id","TICK_SOFT").put("offset_ms",offset)));SyncSupport.Report r=SyncSupport.validate(c,j.toString());t.ok(!r.valid()&&r.copy().contains("$.scenes[1].sfx[0].offset_ms"),"Bad offset accepted");}});
  t.test("seed boundaries and bool rejection",()->{for(long seed:new long[]{0,2147483647L}){JSONObject j=new JSONObject(original);j.put("style",new JSONObject().put("seed",seed));ATSModel.parse(j.toString());}JSONObject j=new JSONObject(original);j.put("style",new JSONObject().put("seed",true));t.reject(j.toString(),"$.style.seed: must be an integer between 0 and 2147483647");});
  t.test("integer fields reject fractional values",()->{JSONObject j=new JSONObject(original);j.put("fps",30.5);t.reject(j.toString(),"$.fps");j=new JSONObject(original);j.put("style",new JSONObject().put("seed",48127.5));t.reject(j.toString(),"$.style.seed");});
  t.test("creator animation remains rejected",()->{for(int i=0;i<6;i++){JSONObject j=new JSONObject(original);j.getJSONObject("caption_style").put("preset",ATSModel.PRESETS[i]).put("animation","POP");t.reject(j.toString(),"$.caption_style.animation");}});
  t.test("Hindi native-font gap is WARN only",()->{JSONObject j=new JSONObject(original);j.getJSONObject("caption_style").put("font","Montserrat");j.getJSONArray("captions").getJSONObject(0).put("text","नमक");SyncSupport.Report r=new SyncSupport.Report();SyncSupport.fontWarnings(c,j,r);t.ok(r.valid()&&r.copy().contains("recommend Poppins"),"Missing font warning");j.getJSONObject("caption_style").put("font","Poppins");r=new SyncSupport.Report();SyncSupport.fontWarnings(c,j,r);t.ok(r.diagnostics.length()==0,"Native Poppins warned");});
  t.test("creator RTL WARN without fake certification",()->{JSONObject j=new JSONObject(original);j.getJSONObject("caption_style").put("preset","Hormozi Style").put("font","DejaVu Sans");j.getJSONArray("captions").getJSONObject(0).put("text","هذا دليل");SyncSupport.Report r=new SyncSupport.Report();SyncSupport.fontWarnings(c,j,r);t.ok(r.valid()&&r.copy().contains(SyncSupport.RTL),"Missing RTL warning");});
  t.test("mode thresholds with infeasible small RICH interval",()->{List<String>x=Arrays.asList("CROSSFADE","FILM_FLASH","DISSOLVE","HARD_CUT","CROSSFADE","DISSOLVE","HARD_CUT","CROSSFADE","DISSOLVE","HARD_CUT","CROSSFADE");JSONObject mode=SyncUsage.counts(x,"BALANCED",.15);t.ok(mode.getJSONObject("thresholds").getJSONObject("RICH").getInt("fancy_min")==3&&mode.getJSONObject("thresholds").getJSONObject("RICH").getInt("fancy_max")==2,"Wrong integer thresholds");});
  t.test("exact synthetic MAX package passes native parser/planner",()->{ATSModel m=ATSModel.parse(SyncSupport.asset(c,"synthetic-max.json"));JSONObject usage=SyncUsage.utilization(m,false);t.ok(usage.getString("mode").equals("MAX")&&usage.getInt("noncut_boundaries")==11&&usage.getInt("fancy_boundaries")==3&&usage.getInt("sfx_cue_count")==3&&usage.getJSONObject("moments_by_type").getInt("DATE_CARD")==2,"MAX mismatch "+usage);});
  t.test("exact final 34-scene RICH package compatibility",()->{String content=SyncSupport.asset(c,"final-rich.json");SyncSupport.Report report=SyncSupport.validate(c,content);t.ok(report.valid(),report.copy());JSONObject usage=SyncUsage.utilization(ATSModel.parse(content),false);t.ok(usage.getString("mode").equals("RICH")&&usage.getInt("noncut_boundaries")==22&&usage.getInt("fancy_boundaries")==8&&usage.getInt("sfx_cue_count")==6,"RICH mismatch "+usage);});
  t.test("real Hindi RICH caption frame rendered with bundled Poppins",()->{ATSModel m=ATSModel.parse(SyncSupport.asset(c,"final-rich.json"));MediaFiles media=new MediaFiles(c);for(ATSModel.Scene scene:m.scenes)media.images.put(scene.id,t.project.media.images.get("001"));Compositor comp=new Compositor(c,m,media);Bitmap frame=Bitmap.createBitmap(360,640,Bitmap.Config.ARGB_8888);try{comp.render(frame,30);try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(t.output,"hindi-rich.png"))){frame.compress(Bitmap.CompressFormat.PNG,100,out);}}finally{frame.recycle();comp.close();}});
  t.test("explicit effects honored at all energies and zero frequency",()->{List<String>before=null;for(String energy:new String[]{"SUBTLE","BALANCED","HIGH_ENERGY"}){JSONObject j=new JSONObject(SyncSupport.asset(c,"final-rich.json"));j.getJSONObject("direction").put("energy",energy).put("transition_frequency",0);ATSModel m=ATSModel.parse(j.toString());List<String>types=new ArrayList<>();for(ATSModel.Scene s:m.scenes)types.add(s.transition+":"+s.transitionFrames);if(before!=null)t.ok(before.equals(types),"Explicit transitions changed with energy");before=types;}});
  t.test("same-cut transition and scene SFX reject close cues",()->{JSONObject j=new JSONObject(original);j.getJSONArray("scenes").getJSONObject(1).put("transition_config",new JSONObject().put("sfx","WHOOSH_SOFT")).put("sfx",new JSONArray().put(new JSONObject().put("id","TICK_SOFT")));t.reject(j.toString(),"$.scenes[1].sfx: cue is within 350 ms of another explicit cue");});
  t.test("variant AUTO accepted and cut SFX disabled",()->{JSONObject j=new JSONObject(original);j.getJSONArray("scenes").getJSONObject(1).put("sfx",new JSONArray().put(new JSONObject().put("id","TICK_SOFT").put("variant","AUTO")));ATSModel m=ATSModel.parse(j.toString());t.ok(SyncUsage.utilization(m,false).getInt("sfx_cue_count")==1,"AUTO not resolved");j.getJSONObject("direction").put("sfx_enabled",false);t.ok(SyncUsage.utilization(ATSModel.parse(j.toString()),false).getInt("sfx_cue_count")==0,"Disabled SFX counted");});
  t.test("canvas override save/reopen keeps original JSON",()->{for(String orientation:new String[]{"VERTICAL","HORIZONTAL","SQUARE","PORTRAIT"}){Project p=new Project(new MediaFiles(c));p.load(t.project.save().toString());String script=p.script;p.overrides.put("orientation",orientation);p.resolve();Project q=new Project(new MediaFiles(c));q.load(p.save().toString());t.ok(q.model.orientation.equals(orientation)&&q.script.equals(script),"Canvas override lost/rewrote JSON");}});
  t.test("low FPS noncuts need four frames",()->{JSONObject j=new JSONObject(original);j.put("fps",10);j.getJSONArray("scenes").getJSONObject(1).put("transition","CROSSFADE").put("transition_config",new JSONObject().put("frames",4));ATSModel m=ATSModel.parse(j.toString());t.ok(m.scenes.get(1).transitionFrames==4,"Minimum transition fit drift");});
  t.test("Android transition defaults use Windows banker rounding",()->{JSONObject j=new JSONObject(original);j.put("fps",25);j.getJSONArray("scenes").getJSONObject(1).put("transition","CROSSFADE");ATSModel m=ATSModel.parse(j.toString());t.ok(m.scenes.get(1).transitionFrames==10,"25-fps defaults drift");});
  t.test("copy diagnostics escapes pipes and newlines",()->{SyncSupport.Report r=new SyncSupport.Report();r.add("$.project_title","range","x|y\nz","a|b\nc","ERROR");t.ok(r.copy().split("\n").length==3&&r.copy().contains("\\u007c"),"Broken diagnostic rows");});
  t.test("prompt menu opens and Copy copies complete original text",()->{t.runOnMainSync(()->{Button menu=button(a.getWindow().getDecorView(),"⋮");if(menu!=null)menu.performClick();});Thread.sleep(350);t.ok(a.overflowMenu!=null&&a.overflowMenu.getMenu().findItem(7).getTitle().toString().equals("Main Master Prompt V5.2.5"),"Prompt missing from menu");t.picture("13-menu");t.runOnMainSync(()->a.overflowMenu.getMenu().performIdentifierAction(7,0));Thread.sleep(1500);t.ok(a.masterPromptDialog!=null&&a.masterPromptDialog.isShowing(),"Prompt dialog did not open");t.picture("09-master-prompt");Button copy=a.masterPromptDialog.getButton(AlertDialog.BUTTON_POSITIVE);t.ok(copy!=null&&copy.getText().toString().equalsIgnoreCase("Copy"),"Copy not visible: "+(copy==null?"null":copy.getText().toString()));t.runOnMainSync(copy::performClick);Thread.sleep(300);ClipboardManager clipboard=(ClipboardManager)c.getSystemService(Context.CLIPBOARD_SERVICE);String expected=a.masterPromptText();String actual=clipboard.getPrimaryClip()==null?"":clipboard.getPrimaryClip().getItemAt(0).coerceToText(c).toString();try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(t.output,"clipboard-roundtrip.json"))){out.write(new JSONObject().put("expected_characters",expected.length()).put("actual_characters",actual.length()).put("actual_prefix",actual.substring(0,Math.min(80,actual.length()))).put("match",expected.equals(actual)).toString(2).getBytes("UTF-8"));}t.ok(expected.equals(actual),"Clipboard mismatch expected="+expected.length()+" actual="+actual.length()+" prefix="+actual.substring(0,Math.min(35,actual.length())));});
  t.test("real validation dialog Copy and utilization button",()->{t.runOnMainSync(()->a.showValidation(null));Thread.sleep(1500);Button copy=a.validationDialog.getButton(AlertDialog.BUTTON_NEUTRAL);t.ok(copy!=null&&copy.getText().toString().equalsIgnoreCase("Copy errors for ChatGPT"),"Real Copy errors button absent: "+(copy==null?"null":copy.getText().toString()));t.runOnMainSync(copy::performClick);Thread.sleep(250);ClipboardManager cb=(ClipboardManager)c.getSystemService(Context.CLIPBOARD_SERVICE);t.ok(cb.getPrimaryClip().getItemAt(0).coerceToText(c).toString().startsWith(SyncSupport.HEADER),"Wrong clipboard errors header");t.runOnMainSync(a::showUtilization);Thread.sleep(300);t.picture("10-utilization");copy=a.utilizationDialog.getButton(AlertDialog.BUTTON_NEUTRAL);t.ok(copy!=null&&copy.getText().toString().equalsIgnoreCase("Copy utilization"),"Utilization Copy absent");t.runOnMainSync(copy::performClick);Thread.sleep(250);t.ok(cb.getPrimaryClip().getItemAt(0).coerceToText(c).toString().startsWith("Mode "),"Utilization clipboard failed");});
  t.test("timeline thumbnail worker finishes and UI stays usable",()->{t.runOnMainSync(a::build);Thread.sleep(1400);t.picture("11-timeline-thumbnails");t.runOnMainSync(()->a.testFrame(91));Thread.sleep(600);t.picture("12-preview");});
 }
}
